{"content":"def digit_sum(n):
    s = 0
    while n:
        s += n % 10
        n //= 10
    return s

count = 0
for n in range(1, 10_000_001):
    if n % 7 == 0:
        if digit_sum(n) == 30:
            count += 1
print(count)

# Write to answer.txt
with open('answer.txt', 'w') as f:
    f.write(str(count))","path":"compute.py"}
